import { Injectable, NotFoundException } from "@nestjs/common";
import { PrismaService } from "src/prisma/prisma.service";
import { CreateWorkspaceDto } from "./dto/createWorkspacesDTO";

@Injectable()
export class WorkspacesService {
  constructor(private readonly prisma: PrismaService) { }

  async create(ownerId: string, dto: CreateWorkspaceDto) {
    return await this.prisma.workspace.create({
      data: {
        ownerId,
        title: dto.title,
      },
    });
  }

  async getMine(ownerId: string) {
    return await this.prisma.workspace.findMany({
      where: {
        ownerId,
      },
      orderBy: {
        createdAt: "asc",
      },
    });
  }

  async getOne(ownerId: string, id: string) {
    const workspace = await this.prisma.workspace.findFirst({
      where: {
        id,
        ownerId,
      },
      include: {
        notes: {
          where: {
            deletedAt: null,
          },
          orderBy: {
            updatedAt: "desc",
          },
        },
        tasks: {
          where: {
            deletedAt: null,
          },
          orderBy: {
            createdAt: "asc",
          },
        },
      },
    });

    if (!workspace) {
      throw new NotFoundException("Workspace не найден");
    }

    return workspace;
  }

  async bootstrap(ownerId: string) {
    const existing = await this.prisma.workspace.findFirst({
      where: {
        ownerId,
      },
      include: { folders: true },
      orderBy: {
        createdAt: "asc",
      },
    });

    if (existing) {
      return existing;
    }

    return this.prisma.workspace.create({
      data: {
        ownerId,
        title: "My Workspace",
        folders: {
          create: [
            { name: "notes", kind: "NOTES" },
            { name: "tasks", kind: "TASKS" },
          ],
        },
      },
      include: {
        folders: true,
      },
    });
  }
}
